#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        // Move element from pos to n-1
        if(pos!=n-1){
            int x=pos+1, y=1;
            if(x+y<n){ // pos+2<n
                doOp(x,y);
                pos=n-1;
            } else {
                // pos=n-2, x=n-1, y=1, x+y=n not <n
                // Use y=1, x=n-2 to move element at n-2... wait pos=n-2
                // element at n-2: use x=pos, y=1 → element at pos in middle? No.
                // Actually if n>=3: x=1,y=1 swaps first and last
                doOp(1,1);
                for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                if(pos==placed) continue;
                if(pos!=n-1){x=pos+1;y=1;if(x+y<n){doOp(x,y);pos=n-1;}}
            }
        }
        if(pos==placed) continue;
        // Move element from n-1 to placed
        if(placed+2<n){
            doOp(1,placed+1);
            // element at n-1 → position placed
        } else if(placed+1<n && placed>0){
            // placed=n-2: need x+y<n, y=placed+1=n-1, x>=1: x+n-1<n→x<1 impossible
            doOp(1,1);
            // retry
            placed--;
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
